const symbols={tab:'Приёмы',title:'Приёмы для ОГЭ и олимпиад',rows:[
[ic('for i in range(n)'),'Формат «сначала n»','Прочитать ровно n чисел','n = 3 → три input()'],
[ic('while x != 0'),'Формат «до нуля»','Читать, пока не встретится 0; 0 не обрабатывать','12, 7, 30, 0 → три числа'],
[ic('map(int, input().split())'),'Числа в одной строке','Разрезать строку по пробелам и превратить куски в числа','«3 17 4» → 3, 17, 4'],
[ic('x % k == 0'),'Кратность','x делится на k без остатка','36 % 4 == 0 → да'],
[ic('x % 10'),'Последняя цифра','Остаток от деления на 10','1236 % 10 = 6'],
[ic('x // 10 % 10'),'Цифра десятков','Отбросили последнюю цифру и взяли новую последнюю','1236 // 10 % 10 = 3'],
[ic('m = 30001'),'Старт минимума','Число больше любого из ограничения','потом if x < m: m = x'],
[ic('(a + b - 1) // b'),'Деление вверх','Сколько коробок по b для a предметов','(6 + 3) // 4 = 2'],
[ic('s[i] == s[i - 1]'),'Сравнить с предыдущим','Серии одинаковых подряд','RRG → одна пара'],
[ic('and / or / not'),'Логика','and — оба; or — хотя бы одно; not — наоборот','10 > 10 — ложь']
],after:`<div class="box tip" style="margin-top:14px"><b>Самое важное</b>Перед отправкой — крайние случаи: одно число, подходящих нет, граница условия.</div>`};

/* ======================= widget ======================= */
function onTheory(root){const el=root.querySelector('#w-trace');if(!el)return;
  el.innerHTML=`<pre class="code" style="margin:0 0 8px">s = 0
k = 1
while s &lt; <span id="tN">10</span>:
    s = s + k
    k = k + 2
print(k)</pre>
<label>N = <output id="oN">10</output><input type="range" id="sN" min="1" max="60" step="1" value="10"></label>
<div class="tbl" id="tTbl"></div><div id="tOut" style="margin-top:6px"></div>`;
  const g=s=>el.querySelector(s);
  const upd=()=>{const N=+g('#sN').value;g('#oN').textContent=N;g('#tN').textContent=N;
    let s=0,k=1,step=0;let rows=`<tr><td>старт</td><td>${s}</td><td>${k}</td><td>${s} &lt; ${N}? ${s<N?'да':'нет'}</td></tr>`;
    while(s<N){s+=k;k+=2;step++;rows+=`<tr><td>виток ${step}</td><td>${s}</td><td>${k}</td><td>${s} &lt; ${N}? ${s<N?'да → ещё виток':'<b>нет → выход</b>'}</td></tr>`;}
    g('#tTbl').innerHTML=`<table class="sym"><thead><tr><th>шаг</th><th>s</th><th>k</th><th>условие</th></tr></thead><tbody>${rows}</tbody></table>`;
    g('#tOut').innerHTML=`Программа напечатает <b>${k}</b> (витков цикла: ${step}).`;};
  g('#sN').addEventListener('input',upd);upd();}

/* ======================= generators ======================= */
const gens=[];
const G=(lvl,make,o)=>{o=o||{};gens.push({lvl,make,star:o.star,rule:o.rule});};

/* ---------- L0: стратегия ---------- */
G(0,()=>{const ok='прочитать условие → решить на примере руками → написать код → проверить крайние случаи';
const bad=['сразу написать код → запустить на примере из условия → отправить','написать код → прочитать условие → проверить крайние случаи → решить на примере','решить на примере → отправить ответ → прочитать условие → написать код'];
const opts=shuffle([ok,...bad]);
return {type:'choice',q:'Какой порядок действий при решении задачи на программирование правильный?',opts,ans:opts.indexOf(ok),
short:'Сначала понять и придумать, потом писать, потом пытаться сломать.',
explain:`Правило четырёх шагов: <b>${ok}</b>.<br>Почему не «сразу код»: пока ты не решил задачу руками, ты не знаешь алгоритма — код получится наугад. А пример из условия обычно самый простой; ошибки прячутся в крайних случаях (одно число, подходящих нет, граница условия).`,
explain2:'Представь, что строишь шалаш. Сначала смотришь, что просят (прочитать условие), рисуешь план на бумажке (пример руками), строишь (код) и потом трясёшь его, проверяя, не развалится ли (крайние случаи). Строить без плана — долго и криво.'};},{rule:true});
G(0,()=>{const ok='тест на границе возможного: одно число, все одинаковые, подходящих нет, ноль, самое большое число';
const bad=['любой длинный тест со случайными числами','тест из примера в условии задачи','тест, на котором программа точно работает'];
const opts=shuffle([ok,...bad]);
return {type:'choice',q:'Что такое <b>крайний случай</b> (крайний тест)?',opts,ans:opts.indexOf(ok),
short:'Крайний случай — «на краю»: самый маленький, пустой, одинаковый, граничный ввод.',
explain:`Крайний случай — это ввод <b>на краю</b> того, что разрешено условием: ${ok}. Именно на них ломается большинство программ: например, минимум, начатый с 0, или <code>range(1, n)</code>, теряющий одно число.<br>Пример из условия — обычно «удобный», он ошибку часто не показывает.`,
explain2:'Мост проверяют не пешеходом, а самым тяжёлым грузовиком, который по правилам может по нему ехать. Крайний тест — это «самый тяжёлый грузовик» для программы: минимум данных, максимум данных, граница условия.'};},{rule:true});
G(0,()=>{const sc=pick([
 {t:'Найти минимальное из n чисел.',ok:'n = 1 (одно число)',bad:['n = 5, числа 3, 8, 1, 9, 4','n = 4, числа 10, 20, 30, 40, но в другом порядке','n = 3, числа 2, 4, 6'],why:'одно число — сам себе минимум; программа, которая где-то делает «n − 1» сравнений неправильно, сломается'},
 {t:'Посчитать, сколько чисел кратны 7.',ok:'ни одно число не кратно 7 (ответ 0)',bad:['числа 7, 14, 3, 21','числа 14, 28, 5','числа 70, 1, 2'],why:'ответ 0 — особый случай: надо убедиться, что программа печатает 0, а не ничего'},
 {t:'Найти максимальное чётное число; если чётных нет, вывести NO.',ok:'все числа нечётные',bad:['числа 4, 8, 2','числа 10, 3, 6','числа 2, 7, 12'],why:'именно здесь должно напечататься NO — ветка, которую обычные примеры не проверяют'},
 {t:'Сколько чисел больше 10?',ok:'среди чисел есть ровно 10',bad:['числа 1, 2, 3','числа 50, 60, 70','числа 11, 25, 3'],why:'10 — граница: «больше 10» не включает само 10. Перепутаешь > и >= — этот тест поймает'}]);
const opts=shuffle([sc.ok,...sc.bad]);
return {type:'choice',q:`Задача: «${sc.t}» Какой тест здесь — <b>крайний случай</b>, который обязательно стоит проверить?`,opts,ans:opts.indexOf(sc.ok),
short:`«${sc.ok}» — ${sc.why}.`,
explain:`Крайний тест — тот, что стоит на границе условия. Здесь это <b>${sc.ok}</b>: ${sc.why}.<br>Остальные варианты — обычные «средние» тесты: программа с типичной ошибкой их, скорее всего, пройдёт.`,
explain2:`Спроси себя: «На каком вводе моя программа <b>может повести себя не так, как обычно</b>?» Обычно это пустой результат, одно значение или граница. Для этой задачи — ${sc.ok}.`};});
G(0,()=>{const k=pick([3,4,5,7]);let a;do{a=rl(6,1,40);}while(!a.some(x=>x%k===0));const good=a.filter(x=>x%k===0);
return {type:'num',q:`Шаг 2 стратегии — реши руками на примере. Задача: «Сколько чисел кратны ${k}?» Пример ввода: ${a.join(', ')}. Какой должен быть ответ?`,ans:good.length,
short:`Кратны ${k}: ${good.join(', ')} — всего ${good.length}.`,
explain:`Проверяем каждое число — делится ли на ${k} без остатка:<br>${a.map(x=>`${x} — ${x%k===0?'делится ✅':`остаток ${x%k} ❌`}`).join('<br>')}<br>Подходят ${good.join(', ')} → ответ <b>${good.length}</b>. Именно так будет работать и программа: перебирает числа и увеличивает счётчик.`,
explain2:`Ставь галочку возле каждого числа из таблицы умножения на ${k} (${range(1,9).map(i=>k*i).join(', ')}, …). Галочки: ${good.join(', ')}. Их ${good.length}. Счётчик в программе — это и есть «количество галочек».`};});

/* ---------- L1: ввод ---------- */
G(1,()=>{const ok='n = int(input())\nfor i in range(n):\n    x = int(input())';
const b1='n = int(input())\nfor i in range(1, n):\n    x = int(input())';
const b2='n = int(input())\nfor i in range(n):\n    x = input()';
const b3='n = int(input())\nwhile n != 0:\n    x = int(input())';
const all=shuffle([ok,b1,b2,b3]);
return {type:'choice',q:'Вход: сначала количество чисел n, потом n чисел, каждое в своей строке. Какой фрагмент правильно читает все числа?',opts:all.map(C),ans:all.indexOf(ok),
short:'range(n) — ровно n повторений, int() — превращает текст в число.',
explain:`Правильно:${C(ok)}• <code>range(n)</code> даёт ровно n повторений (0, 1, …, n − 1).<br>• <code>range(1, n)</code> — только n − 1 повторение, одно число потеряется.<br>• <code>x = input()</code> без int — x будет <b>текстом</b>, и <code>x % 4</code> выдаст ошибку.<br>• <code>while n != 0</code> — n внутри не меняется, цикл бесконечный.`,
explain2:'Проверь каждый вариант на маленьком вводе: n = 2, числа 5 и 7. Сколько раз выполнится input() внутри цикла? В правильном — 2 раза, и оба раза получится число. В range(1, 2) — 1 раз. В варианте с while — бесконечно.'};},{rule:true});
G(1,()=>{const ok='читает строку, режет её по пробелам и превращает кусочки в числа a и b';
const bad=['читает два числа из двух разных строк','складывает два введённых числа','читает одно число и делит его пополам'];
const opts=shuffle([ok,...bad]);
return {type:'choice',q:`Что делает строка ${ic('a, b = map(int, input().split())')}?`,opts,ans:opts.indexOf(ok),
short:'input() — строка, split() — по пробелам, map(int, …) — в числа.',
explain:`Разбираем по кусочкам: <code>input()</code> читает <b>одну строку</b>, например «3 17»; <code>.split()</code> режет её по пробелам → ['3', '17']; <code>map(int, …)</code> делает из каждого кусочка число; <code>a, b =</code> раскладывает: a = 3, b = 17.<br>Из двух разных строк она читать <b>не</b> умеет — для этого нужны два input().`,
explain2:'Представь батон: input() — весь батон, split() — нож, который режет по пробелам, map(int, …) — превращает каждый кусочек из «текста» в «число», а a, b = — раскладывает два кусочка по двум тарелкам.'};},{rule:true});
G(1,()=>{const k=pick([2,3,5]);let a;do{a=rl(R(4,7),1,30);}while(!a.some(x=>x%k===0)||a.every(x=>x%k===0));
const cnt=a.filter(x=>x%k===0).length;
const code=`c = 0\nx = int(input())\nwhile x != 0:\n    if x % ${k} == 0:\n        c += 1\n    x = int(input())\nprint(c)`;
return {type:'num',q:`Что выведет программа, если ввести числа ${a.join(', ')}, 0 (каждое в своей строке)?${C(code)}`,ans:cnt,
short:`Кратны ${k}: ${a.filter(x=>x%k===0).join(', ')} → ${cnt}. Ноль — «стоп», он не считается.`,
explain:`Программа читает числа, пока не встретит 0, и считает те, что делятся на ${k}:<br>${a.map(x=>`${x}: ${x%k===0?'c += 1':'не кратно'}`).join('<br>')}<br>0: условие <code>x != 0</code> ложно → выход из цикла. Печатается <b>${cnt}</b>.`,
explain2:`Сам 0 в цикл не попадает: его прочитали в последней строке тела, потом проверили условие while — и вышли. Поэтому, хотя 0 % ${k} == 0, он не посчитан. Остаются только ${a.join(', ')}; из них на ${k} делятся ${cnt}.`};});
G(1,()=>{const k=pick([3,4,6,7]);
const mk=()=>{const n=R(4,8);const a=rl(n,1,200);if(!a.some(x=>x%k===0))a[R(0,n-1)]=k*R(1,20);return a;};
const ins=[mk(),mk(),[k*R(2,9)],[k+1,k*2+1],mk()];
const tests=ins.map(a=>({in:J(a.concat([0])),out:String(a.filter(x=>x%k===0).length)}));
return {type:'code',q:`<b>Формат «до нуля».</b> Программа получает на вход натуральные числа, каждое в своей строке. Количество чисел неизвестно, последовательность заканчивается числом 0 (0 — признак конца, его не учитывают). Выведи, сколько среди них чисел, <b>кратных ${k}</b>.<br>Пример: ввод ${k}, ${k+1}, ${2*k}, 0 → вывод 2.`,
starter:`count = 0\nx = int(input())\nwhile x != 0:\n    # проверь x и увеличь count, если нужно\n\n    x = int(input())\nprint(count)`,
solution:`count = 0\nx = int(input())\nwhile x != 0:\n    if x % ${k} == 0:\n        count += 1\n    x = int(input())\nprint(count)`,tests,
hint:`Внутри цикла нужно одно условие: <code>if x % ${k} == 0:</code> и под ним <code>count += 1</code>.`,
explain:`Идея: перебираем числа, пока не встретим 0, и ставим «галочку» за каждое кратное ${k}.<br>1) Первое число читаем до цикла.<br>2) <code>while x != 0</code> — пока не стоп.<br>3) <code>if x % ${k} == 0: count += 1</code>.<br>4) В конце тела читаем следующее число — иначе цикл станет бесконечным.<br>5) После цикла печатаем count. Важный тест: «подходящих нет» — должно напечататься 0.`,
explain2:`Сравни с форматом «сначала n»: там цикл for знает, сколько раз крутиться. Здесь мы не знаем, поэтому крутимся «пока не 0». Схема всегда одна: <b>прочитал → while x != 0 → обработал → прочитал следующее</b>. Обработка здесь — проверка кратности ${k} через остаток.`};});
G(1,()=>{const tests=[['23 50','20','0 10'],['10 0','0','10 0'],['0 0','1440','0 0'],['12 30','45','13 15'],['5 5','3000','7 5'],['23 59','1','0 0']].map(t=>({in:t[0]+'\n'+t[1],out:t[2]}));
return {type:'code',q:`<b>Часы</b> (по мотивам школьного этапа ВсОШ). В первой строке через пробел — часы h и минуты m (сейчас h:m, 24-часовой формат). Во второй строке — число k минут. Выведи через пробел, сколько часов и минут покажут часы через k минут.<br>Пример: ввод «23 50» и «20» → вывод «0 10».`,
starter:`h, m = map(int, input().split())\nk = int(input())\n# переведи всё в минуты от полуночи\n`,
solution:`h, m = map(int, input().split())\nk = int(input())\nt = (h * 60 + m + k) % 1440\nprint(t // 60, t % 60)`,tests,
hint:'Переведи время в минуты от полуночи: h·60 + m. Прибавь k. В сутках 1440 минут — возьми остаток. Потом обратно: часы = t // 60, минуты = t % 60.',
explain:`Стратегия «на примере»: 23:50 — это 23·60 + 50 = 1430 минут от полуночи. Плюс 20 → 1450. В сутках 24·60 = 1440 минут, поэтому 1450 % 1440 = 10 минут от полуночи → 0 ч 10 мин.<br>Код: <code>t = (h * 60 + m + k) % 1440</code>, затем <code>print(t // 60, t % 60)</code>.<br>Крайние случаи: k = 0; k ровно сутки (1440); k больше двух суток (3000).`,
explain2:'Часы — это «круг» из 1440 минут. Остаток от деления на 1440 как раз и делает круг: дошёл до конца — начинаешь с нуля. Это тот же приём, что и последняя цифра числа (% 10), только круг длиннее.'};});

/* ---------- L2: счётчик и сумма ---------- */
G(2,()=>{const d=R(1,9);const ok=`x % 10 == ${d}`;const opts=shuffle([ok,`x // 10 == ${d}`,`x % ${d} == 0`,`x / 10 == ${d}`]);
return {type:'choice',q:`Как в Python проверить, что число x <b>оканчивается на ${d}</b>?`,opts:opts.map(ic),ans:opts.indexOf(ok),
short:`x % 10 — последняя цифра числа.`,
explain:`Остаток от деления на 10 — это <b>последняя цифра</b>: например, 12${d} % 10 = ${d}. Поэтому условие: <code>${esc(ok)}</code>.<br>• <code>x // 10</code> — число <b>без</b> последней цифры (12${d} // 10 = 12).<br>• <code>x % ${d} == 0</code> — кратность ${d}, совсем другое.<br>• <code>x / 10</code> — дробное деление (12${d} / 10 = 12,${d}).`,
explain2:`Раздели 12${d} конфет по 10 в пакет: получится 12 полных пакетов (это // 10) и ${d} конфет останется (это % 10). Оставшиеся — и есть последняя цифра.`};},{rule:true});
G(2,()=>{const a=R(11,89);const r=pyMod(-a,10);
return {type:'num',q:`Что напечатает Python: ${ic(`print(-${a} % 10)`)}?`,ans:r,
short:`−${a} = 10·(${-Math.ceil(a/10)}) + ${r}, остаток ${r}.`,
explain:`В Python остаток всегда того же знака, что делитель (здесь 10 — положительный), то есть от 0 до 9.<br>Ищем: −${a} = 10·q + r, где 0 ≤ r ≤ 9. Берём q = ${-Math.ceil(a/10)}: 10·(${-Math.ceil(a/10)}) = −${10*Math.ceil(a/10)}, и −${a} − (−${10*Math.ceil(a/10)}) = ${r}.<br>Ответ: <b>${r}</b>. Поэтому последнюю цифру отрицательного числа берут как <code>abs(x) % 10</code> (это было бы ${a%10}).`,
explain2:`Представь числовую прямую с отметками через 10: …, −${10*Math.ceil(a/10)}, −${10*Math.ceil(a/10)-10}, … Число −${a} лежит между ними. Остаток в Python — это расстояние от отметки <b>слева</b> (−${10*Math.ceil(a/10)}) до числа: ${r}.`};},{rule:true});
G(2,()=>{const pr=pick([[4,6],[3,7],[6,4],[7,1],[8,2],[3,1]]);const k=pr[0],d=pr[1];
const goods=range(1,3000).filter(x=>x%k===0&&x%10===d);
const mk=(n,m)=>{const a=rl(n,1,3000);for(let j=0;j<m;j++)a[R(0,n-1)]=pick(goods);return a;};
const ins=[mk(6,2),mk(8,3),[pick(goods)],[k*10],mk(5,0).map(x=>x%k===0&&x%10===d?x+1:x),Array.from({length:4},()=>pick(goods))];
const f=a=>a.filter(x=>x%k===0&&x%10===d).length;
const tests=ins.map(a=>({in:J([a.length].concat(a)),out:String(f(a))}));
return {type:'code',q:`<b>Как в ОГЭ.</b> Напиши программу, которая в последовательности натуральных чисел определяет количество чисел, <b>кратных ${k} и оканчивающихся на ${d}</b>. Сначала вводится количество чисел n, затем n чисел, каждое в своей строке. Числа не превышают 30 000.<br>Пример: n = 3, числа ${goods[0]}, ${goods[0]+1}, ${goods[1]} → вывод 2.`,
starter:`n = int(input())\ncount = 0\nfor i in range(n):\n    x = int(input())\n    # допиши условие\n\nprint(count)`,
solution:`n = int(input())\ncount = 0\nfor i in range(n):\n    x = int(input())\n    if x % ${k} == 0 and x % 10 == ${d}:\n        count += 1\nprint(count)`,tests,
hint:`Два условия сразу — через <code>and</code>: <code>x % ${k} == 0 and x % 10 == ${d}</code>.`,
explain:`1) Читаем n, счётчик = 0.<br>2) n раз читаем число x.<br>3) Кратно ${k} — <code>x % ${k} == 0</code>; оканчивается на ${d} — <code>x % 10 == ${d}</code>. Нужны <b>оба</b> условия → <code>and</code>.<br>4) Печатаем счётчик после цикла (без отступа!).<br>Проверка на примере: ${goods[0]} — подходит, ${goods[0]+1} — нет, ${goods[1]} — подходит → 2.`,
explain2:`Частые ошибки в этой задаче: <code>or</code> вместо <code>and</code> (посчитаются числа, у которых выполнено только одно условие), <code>print</code> с отступом внутри цикла (напечатается n раз), <code>range(1, n)</code> (потеряется одно число). Пройди свою программу по примеру из условия глазами, строка за строкой.`};});
G(2,()=>{const d=R(1,9);
const mk=(n)=>rl(n,1,500);
const ins=[mk(6),mk(7),[10+d],[20,30,40],mk(5),[d,d,d]];
ins.forEach((a,i)=>{if(i!==3&&!a.some(x=>x%10===d))a[0]=a[0]-a[0]%10+d;});
const f=a=>{const g=a.filter(x=>x%10===d);return g.length+'\n'+g.reduce((p,q)=>p+q,0);};
const tests=ins.map(a=>({in:J([a.length].concat(a)),out:f(a)}));
return {type:'code',q:`Даны n и затем n натуральных чисел (каждое в своей строке). Найди, <b>сколько</b> чисел оканчиваются на ${d}, и их <b>сумму</b>. Выведи два числа, каждое в своей строке: сначала количество, потом сумму. Если таких чисел нет — выведи 0 и 0.`,
starter:`n = int(input())\ncount = 0\ns = 0\nfor i in range(n):\n    x = int(input())\n\nprint(count)\nprint(s)`,
solution:`n = int(input())\ncount = 0\ns = 0\nfor i in range(n):\n    x = int(input())\n    if x % 10 == ${d}:\n        count += 1\n        s += x\nprint(count)\nprint(s)`,tests,
hint:`Под одним <code>if x % 10 == ${d}:</code> — сразу две строки: увеличить count и прибавить x к s.`,
explain:`Нам нужны два «накопителя»: счётчик (прибавляем 1) и сумма (прибавляем само число). Оба меняются, только если последняя цифра ${d}:<pre class="code">if x % 10 == ${d}:\n    count += 1\n    s += x</pre>Тест «20, 30, 40» проверяет крайний случай: подходящих нет → 0 и 0.`,
explain2:`Сравни: счётчик — это «сколько галочек», сумма — «сложи числа с галочками». Например, для 1${d}, 7, 2${d}: галочки у 1${d} и 2${d} → count = 2, s = ${10+d+20+d}.`};});
G(2,()=>{const a=R(1,5),b=a+R(8,14),k=pick([2,3,4]);let s=0;const used=[];for(let i=a;i<b;i++)if(i%k===0){s+=i;used.push(i);}
const code=`s = 0\nfor i in range(${a}, ${b}):\n    if i % ${k} == 0:\n        s += i\nprint(s)`;
return {type:'num',q:`Что выведет программа?${C(code)}`,ans:s,
short:`i от ${a} до ${b-1}; кратные ${k}: ${used.join(' + ')} = ${s}.`,
explain:`<code>range(${a}, ${b})</code> — это числа от ${a} до <b>${b-1}</b> (правая граница не входит!).<br>Из них кратны ${k}: ${used.join(', ')}.<br>Сумма: ${used.join(' + ')} = <b>${s}</b>.`,
explain2:`Выпиши все i подряд и подчеркни подходящие: ${range(a,b-1).map(i=>i%k===0?`<b>${i}</b>`:i).join(', ')}. Число ${b} не пишем — range останавливается перед ним. Сложи подчёркнутые: ${s}.`};});

/* ---------- L3: минимум / максимум ---------- */
G(3,()=>{const ok='ни одно натуральное число не меньше 0, поэтому m останется 0 — а такого числа во вводе нет';
const bad=['0 — это не число, Python выдаст ошибку','с 0 программа работает правильно, просто медленнее','минимум надо начинать с 1, потому что числа натуральные'];
const opts=shuffle([ok,...bad]);
return {type:'choice',q:`Ищем минимум из натуральных чисел. Почему нельзя начинать с ${ic('m = 0')}?`,opts,ans:opts.indexOf(ok),
short:'m = 0 никогда не обновится: x < 0 для натуральных всегда ложно.',
explain:`Условие обновления — <code>if x &lt; m</code>. При m = 0 для натуральных x оно <b>всегда ложно</b>, и программа напечатает 0, которого во вводе не было.<br>Правильно — начать с числа, большего любого возможного (если числа ≤ 30 000, то <code>m = 30001</code>), или с первого прочитанного числа.<br>Вариант «начать с 1» тоже неверный: если все числа больше 1, ответ будет 1.`,
explain2:'Представь соревнование «кто ниже ростом». Если поставить в «чемпионы» гнома ростом 0 см, его никто не победит — и победителем объявят гнома, хотя он даже не участвовал. Начальный чемпион должен быть «великаном», которого победит первый же участник.'};},{rule:true});
G(3,()=>{const d=pick([3,7,9]);
const code=`n = int(input())\nm = 0\nfor i in range(n):\n    x = int(input())\n    if x % 10 == ${d} and x < m:\n        m = x\nprint(m)`;
const opts=shuffle(['строка 2: m = 0','строка 1: n = int(input())','строка 4: x = int(input())','строка 7: print(m)']);
return {type:'choice',q:`Программа должна найти минимальное число, оканчивающееся на ${d} (числа натуральные, не больше 30 000, такое число точно есть). В какой строке ошибка?${C(code)}`,opts,ans:opts.indexOf('строка 2: m = 0'),
short:'m = 0 — условие x < m никогда не выполнится. Нужно m = 30001.',
explain:`Пусть ввод: 3, числа 1${d}, 5${d}, 8. Трассировка: m = 0; 1${d} &lt; 0? нет; 5${d} &lt; 0? нет; 8 — не оканчивается на ${d}. Печатается <b>0</b> — неверно, правильный ответ 1${d}.<br>Ошибка в <b>строке 2</b>: начать надо с числа больше любого возможного: <code>m = 30001</code>.`,
explain2:'Остальные строки — стандартный шаблон «формата А»: прочитать n, n раз прочитать x, в конце напечатать. А вот стартовое значение минимума — классическая ловушка: начинать надо с «великана», а не с нуля.'};});
G(3,()=>{const d=R(1,9);
const mk=n=>{const a=rl(n,1,30000);a[R(0,n-1)]=R(1,2999)*10+d;return a;};
const ins=[mk(6),mk(8),[30000-10+d],[d,d+10,d+20],mk(5),[29990+d,5,6,15000+d]];
const f=a=>Math.min(...a.filter(x=>x%10===d));
const tests=ins.map(a=>({in:J([a.length].concat(a)),out:String(f(a))}));
return {type:'code',q:`<b>Как в ОГЭ.</b> Напиши программу, которая в последовательности натуральных чисел определяет <b>минимальное число, оканчивающееся на ${d}</b>. Сначала вводится n, затем n чисел (каждое в своей строке). Числа не превышают 30 000. Гарантируется, что хотя бы одно число оканчивается на ${d}.`,
starter:`n = int(input())\nm = 0\nfor i in range(n):\n    x = int(input())\n    if x % 10 == ${d} and x < m:\n        m = x\nprint(m)`,
solution:`n = int(input())\nm = 30001\nfor i in range(n):\n    x = int(input())\n    if x % 10 == ${d} and x < m:\n        m = x\nprint(m)`,tests,
hint:'В заготовке спрятана классическая ошибка в стартовом значении m. Найди и исправь.',
explain:`Алгоритм: «чемпион» m, сравниваем только подходящие числа (оканчиваются на ${d}).<br>Ключевая строка — <code>m = 30001</code>: это больше любого числа из ограничения, поэтому первое же подходящее число станет чемпионом.<br>С <code>m = 0</code> условие <code>x &lt; m</code> никогда не выполнится, и программа напечатает 0.<br>Тест «${29990+d}, 5, 6, ${15000+d}» проверяет, что числа, не оканчивающиеся на ${d}, не участвуют (5 и 6 меньше, но не подходят).`,
explain2:`Можно и по-другому: <code>m = -1</code> («ещё не нашли») и условие <code>if x % 10 == ${d} and (m == -1 or x &lt; m)</code>. Это работает, даже если ограничение на числа неизвестно.`};});
G(3,()=>{
const mk=n=>rl(n,1,1000);
const ins=[mk(6),[1,3,5,7],[8],mk(7),[5,2],[999,1001,3]];
const f=a=>{const e=a.filter(x=>x%2===0);return e.length?String(Math.max(...e)):'NO';};
const tests=ins.map(a=>({in:J([a.length].concat(a)),out:f(a)}));
return {type:'code',q:`Даны n и n натуральных чисел. Выведи <b>максимальное чётное</b> число. Если чётных чисел нет, выведи <b>NO</b>.`,
starter:`n = int(input())\nmx = 0\nfor i in range(n):\n    x = int(input())\n`,
solution:`n = int(input())\nmx = 0\nfor i in range(n):\n    x = int(input())\n    if x % 2 == 0 and x > mx:\n        mx = x\nif mx == 0:\n    print("NO")\nelse:\n    print(mx)`,tests,
hint:'Для максимума натуральных чисел можно начать с mx = 0. Если после цикла mx всё ещё 0 — значит, ни одного чётного не встретилось.',
explain:`1) <code>mx = 0</code> — любое натуральное чётное число больше нуля, поэтому первое же чётное станет чемпионом.<br>2) В цикле: <code>if x % 2 == 0 and x &gt; mx: mx = x</code>.<br>3) После цикла: если mx так и остался 0 — чётных не было → <code>print("NO")</code>, иначе печатаем mx.<br>Крайние тесты: все нечётные (1, 3, 5, 7) → NO; одно число 8 → 8.`,
explain2:'Здесь 0 работает как «флаг»: он означает «пока ничего не нашли». Это возможно, потому что 0 не бывает ответом (числа натуральные). Если бы числа могли быть отрицательными, понадобился бы другой флаг.'};});
G(3,()=>{
const mk=n=>rl(n,1,500);
const ins=[mk(6),[7],[4,4,4],mk(8),[100,1],[3,900,2,899]];
const tests=ins.map(a=>({in:J(a.concat([0])),out:String(Math.max(...a)-Math.min(...a))}));
return {type:'code',q:`<b>Формат «до нуля».</b> Вводятся натуральные числа (не больше 30 000), каждое в своей строке; конец — число 0. Чисел хотя бы одно. Выведи <b>разность между максимальным и минимальным</b> числом.<br>Пример: 5, 9, 2, 0 → 9 − 2 = 7.`,
starter:`mx = 0\nmn = 30001\nx = int(input())\nwhile x != 0:\n    # обнови mx и mn\n\n    x = int(input())\n`,
solution:`mx = 0\nmn = 30001\nx = int(input())\nwhile x != 0:\n    if x > mx:\n        mx = x\n    if x < mn:\n        mn = x\n    x = int(input())\nprint(mx - mn)`,tests,
hint:'Два независимых if: один обновляет максимум, другой — минимум. Не elif! Первое число должно обновить оба.',
explain:`Держим двух чемпионов сразу: mx (старт 0) и mn (старт 30001).<br>Для каждого x: <code>if x &gt; mx: mx = x</code> и отдельно <code>if x &lt; mn: mn = x</code>.<br>Почему не <code>elif</code>: первое число должно стать и максимумом, и минимумом одновременно. С elif оно обновит только mx, и для ввода «7, 0» получится 7 − 30001.<br>В конце <code>print(mx - mn)</code>. Тест «4, 4, 4» → 0.`,
explain2:`Трассировка на 5, 9, 2: x=5 → mx=5, mn=5; x=9 → mx=9; x=2 → mn=2. Итог 9 − 2 = 7. Одно число 7 → mx = mn = 7 → 0.`};});

/* ---------- L4: анализ программы ---------- */
G(4,()=>{const ok='выполнять программу «вручную» по шагам, записывая значения переменных в таблицу';
const bad=['запустить программу много раз с разными числами','угадать ответ по виду программы','переписать программу на другой язык'];
const opts=shuffle([ok,...bad]);
return {type:'choice',q:'Что такое <b>трассировка</b> программы?',opts,ans:opts.indexOf(ok),
short:'Трассировка — ты сам становишься компьютером и ведёшь таблицу значений.',
explain:`Трассировка — это <b>${ok}</b>. Для каждой переменной — столбец, для каждого шага — строка. Перед каждым витком цикла проверяешь условие.<br>На экзамене компьютера для запуска нет, поэтому это единственный надёжный способ ответить «что выведет программа».`,
explain2:'Это как следить за шариком в напёрстках: не угадывать, а аккуратно отслеживать каждое движение. Каждое присваивание — «движение шарика», которое ты записываешь.'};},{rule:true});
G(4,()=>{const st=R(2,5),N=R(15,40);let s=0,k=0;while(s<N){s+=st;k++;}
const code=`s = 0\nk = 0\nwhile s < ${N}:\n    s = s + ${st}\n    k = k + 1\nprint(k)`;
const rows=[];{let ss=0,kk=0;while(ss<N){ss+=st;kk++;rows.push(`виток ${kk}: s = ${ss}, k = ${kk}`);}}
return {type:'num',q:`Что выведет программа?${C(code)}`,ans:k,
short:`s растёт на ${st}: остановится, когда s = ${s} ≥ ${N}; витков ${k}.`,
explain:`Трассируем: s = 0, k = 0.<br>${rows.length>8?rows.slice(0,3).join('<br>')+'<br>…<br>'+rows.slice(-2).join('<br>'):rows.join('<br>')}<br>Теперь ${s} &lt; ${N}? Нет → выход. Печатается k = <b>${k}</b>.`,
explain2:`Без таблицы: цикл крутится, пока s &lt; ${N}, и каждый раз s увеличивается на ${st}. Сколько раз нужно прибавить ${st}, чтобы дойти до ${N} или перешагнуть? ${N} / ${st} ≈ ${(N/st).toFixed(1).replace('.',',')} → округляем вверх: ${k}.`};});
G(4,()=>{const n=R(1000,99999);let m=n,s=0,c=0;const ds=[];while(m>0){ds.push(m%10);s+=m%10;m=Math.floor(m/10);c++;}
const what=pick(['s','c']);
const code=`n = ${n}\ns = 0\nc = 0\nwhile n > 0:\n    s = s + n % 10\n    c = c + 1\n    n = n // 10\nprint(${what})`;
const ans=what==='s'?s:c;
return {type:'num',q:`Что выведет программа?${C(code)}`,ans,
short:what==='s'?`Сумма цифр числа ${n}: ${ds.slice().reverse().join(' + ')} = ${s}.`:`c — количество цифр числа ${n}: ${c}.`,
explain:`Каждый виток: <code>n % 10</code> — последняя цифра, <code>n // 10</code> — отрезает её. Цифры отрезаются справа налево: ${ds.join(', ')}.<br>s накапливает сумму цифр: ${ds.join(' + ')} = ${s}. c считает витки: ${c}.<br>Печатается ${what} = <b>${ans}</b>.`,
explain2:`Таблица: ${(()=>{let m2=n,s2=0,c2=0,o=[];while(m2>0){s2+=m2%10;c2++;m2=Math.floor(m2/10);o.push(`n=${m2}, s=${s2}, c=${c2}`);}return o.join('; ');})()}. Когда n стало 0, цикл закончился.`};});
G(4,()=>{const a=pick([2,3,4]);let b;do{b=pick([3,5,6,7]);}while(b===a||b%a===0);const N=R(15,30);let c=0;const L=[];for(let i=1;i<=N;i++)if(i%a===0||i%b===0){c++;L.push(i);}
const code=`c = 0\nfor i in range(1, ${N+1}):\n    if i % ${a} == 0 or i % ${b} == 0:\n        c = c + 1\nprint(c)`;
return {type:'num',q:`Что выведет программа?${C(code)}`,ans:c,
short:`Числа от 1 до ${N}, кратные ${a} или ${b}: ${c} штук.`,
explain:`i пробегает от 1 до ${N} (до ${N+1}, не включая). Считаем числа, кратные ${a} <b>или</b> ${b} (хотя бы одному):<br>${L.join(', ')}.<br>Всего <b>${c}</b>.`,
explain2:`Можно формулой: кратных ${a}: ${N} // ${a} = ${Math.floor(N/a)}; кратных ${b}: ${Math.floor(N/b)}; кратных обоим (то есть ${a*b/H.gcd(a,b)}): ${Math.floor(N/(a*b/H.gcd(a,b)))} — их посчитали дважды. ${Math.floor(N/a)} + ${Math.floor(N/b)} − ${Math.floor(N/(a*b/H.gcd(a,b)))} = ${c}.`};});
G(4,()=>{const w=pick(['программирование','информатика','олимпиада','алгоритм','переменная','компьютер','клавиатура','трассировка']);const V='аеёиоуыэюя';
const k=[...w].filter(ch=>V.includes(ch)).length;
const code=`s = "${w}"\nk = 0\nfor ch in s:\n    if ch in "аеёиоуыэюя":\n        k = k + 1\nprint(k)`;
return {type:'num',q:`Что выведет программа?${C(code)}`,ans:k,
short:`Гласные в «${w}»: ${[...w].filter(ch=>V.includes(ch)).join(', ')} → ${k}.`,
explain:`Цикл перебирает буквы слова «${w}» и считает те, что есть в строке гласных:<br>${[...w].map(ch=>V.includes(ch)?`<b>${ch}</b>`:ch).join(' ')}<br>Гласных: <b>${k}</b>.`,
explain2:`<code>ch in "аеёиоуыэюя"</code> — проверка «эта буква есть среди гласных?». Пройди по слову пальцем и считай: ${[...w].filter(ch=>V.includes(ch)).map((ch,i)=>`${i+1}) ${ch}`).join(', ')}.`};});

/* ---------- L5: запуски ---------- */
G(5,()=>{const v=pick([{c:'A and B',ok:'когда верны оба условия A и B',bad:['когда верно хотя бы одно из условий','когда оба условия ложны','когда верно ровно одно из условий']},{c:'A or B',ok:'когда верно хотя бы одно из условий A, B (или оба)',bad:['только когда верны оба условия','только когда верно ровно одно условие','когда оба условия ложны']},{c:'not A',ok:'когда условие A ложно',bad:['когда условие A верно','всегда','никогда']}]);
const opts=shuffle([v.ok,...v.bad]);
return {type:'choice',q:`Когда выражение ${ic(v.c)} истинно?`,opts,ans:opts.indexOf(v.ok),
short:`${v.c}: ${v.ok}.`,
explain:`<b>and</b> — «и»: нужны оба. <b>or</b> — «или»: хватит одного (оба тоже можно). <b>not</b> — «не»: переворачивает.<br>Значит, <code>${esc(v.c)}</code> истинно, ${v.ok}.`,
explain2:'Пример из жизни: «Пойду гулять, если тепло <b>и</b> нет дождя» — нужны оба. «Возьму зонт, если дождь <b>или</b> снег» — хватит одного. «Если <b>не</b> устал — пойду на тренировку».'};},{rule:true});
const pairsGen=()=>{const ps=[];while(ps.length<9){const p=[R(-12,14),R(-12,14)];if(!ps.some(q=>q[0]===p[0]&&q[1]===p[1]))ps.push(p);}return ps;};
const condV=[
 {txt:(A,B)=>`s > ${A} or t > ${B}`,f:(s,t,A,B)=>s>A||t>B},
 {txt:(A,B)=>`s > ${A} and t < ${B}`,f:(s,t,A,B)=>s>A&&t<B},
 {txt:(A,B)=>`not (s < ${A}) and t > ${B}`,f:(s,t,A,B)=>!(s<A)&&t>B},
 {txt:(A,B)=>`s >= ${A} or t == ${B}`,f:(s,t,A,B)=>s>=A||t===B}];
const runGen=(variants)=>()=>{let cv,A,B,ps,yes;do{cv=pick(variants);A=R(0,10);B=R(0,10);ps=pairsGen();
 if(cv.txt(A,B).includes('==')){ps[R(0,8)][1]=B;}
 if(Math.random()<0.6)ps[R(0,8)][0]=A;
 yes=ps.filter(p=>cv.f(p[0],p[1],A,B));}while(yes.length<2||yes.length>7);
 const code=`s = int(input())\nt = int(input())\nif ${cv.txt(A,B)}:\n    print("YES")\nelse:\n    print("NO")`;
 const P=p=>`(${minus(p[0])}, ${minus(p[1])})`;
 return {type:'num',q:`Программу запустили 9 раз. Пары (s, t): ${ps.map(P).join('; ')}. Сколько раз она напечатала «YES»?${C(code)}`,ans:yes.length,
 short:`YES для: ${yes.map(P).join('; ')} — ${yes.length} ${plural(yes.length,'раз','раза','раз')}.`,
 explain:`Проверяем условие <code>${esc(cv.txt(A,B))}</code> для каждой пары:<br>${ps.map(p=>`${P(p)} → ${cv.f(p[0],p[1],A,B)?'<b>YES</b>':'NO'}`).join('<br>')}<br>Итого YES: <b>${yes.length}</b>.`,
 explain2:`Разбей условие на части и проверяй каждую отдельно, потом соединяй: <b>and</b> — нужны обе части, <b>or</b> — хватит одной, <b>not</b> переворачивает. Особое внимание — парам, где число <b>равно</b> границе: s = ${A} или t = ${B}. Там важно, стоит ли &gt; или &gt;=.`};};
G(5,runGen([condV[0],condV[1]]));
G(5,runGen([condV[2],condV[3]]));
G(5,()=>{const s=R(-5,20),t=R(-5,20);const kind=pick(['orNO','andYES']);let code,ask,ans;
 if(kind==='orNO'){code=`s = ${s}\nt = ${t}\nif s > A or t > A:\n    print("YES")\nelse:\n    print("NO")`;ask='напечатает «NO»';for(let A=-100;A<=100;A++){if(!(s>A||t>A)){ans=A;break;}}}
 else{code=`s = ${s}\nt = ${t}\nif s < A and t < A:\n    print("YES")\nelse:\n    print("NO")`;ask='напечатает «YES»';for(let A=-100;A<=100;A++){if(s<A&&t<A){ans=A;break;}}}
 const mx=Math.max(s,t);
 return {type:'num',q:`Укажи <b>наименьшее</b> целое значение A, при котором программа ${ask}.${C(code)}`,ans,
 short:kind==='orNO'?`NO, когда ${minus(s)} ≤ A и ${minus(t)} ≤ A, то есть A ≥ ${minus(mx)}.`:`YES, когда A > ${minus(s)} и A > ${minus(t)}, то есть A ≥ ${minus(mx+1)}.`,
 explain:kind==='orNO'?`NO печатается, когда условие <code>s &gt; A or t &gt; A</code> <b>ложно</b>, то есть <b>оба</b> сравнения ложны: ${minus(s)} ≤ A и ${minus(t)} ≤ A. Значит, A ≥ ${minus(mx)}. Наименьшее A = <b>${minus(ans)}</b>.<br>Проверка: при A = ${minus(ans-1)} получим ${minus(mx)} &gt; ${minus(ans-1)} — верно → YES, не подходит.`:`YES печатается, когда оба условия верны: ${minus(s)} &lt; A и ${minus(t)} &lt; A. Значит, A больше большего из чисел, ${minus(mx)}. Строго больше! Наименьшее целое: <b>${minus(ans)}</b>.<br>Проверка: при A = ${minus(mx)} условие ${minus(mx)} &lt; ${minus(mx)} ложно → NO.`,
 explain2:`Можно просто перебирать A по одному около чисел ${minus(s)} и ${minus(t)} и подставлять в условие: ${[ans-2,ans-1,ans].map(A=>`A = ${minus(A)} → ${kind==='orNO'?((s>A||t>A)?'YES':'NO'):((s<A&&t<A)?'YES':'NO')}`).join('; ')}. Первое A, при котором получилось нужное, — ответ.`};});

/* ---------- L6: крайние случаи, ошибки ---------- */
G(6,()=>{const cand=[{t:'одно число (n = 1)',ok:true},{t:'подходящих чисел нет',ok:true},{t:'число, равное границе условия (например, ровно 10 при «больше 10»)',ok:true},{t:'нужное число стоит последним',ok:true},{t:'тест из примера в условии (уже проверен в задаче)',ok:false},{t:'тест, где все числа разные и «удобные»',ok:false}];
const opts=shuffle(sample(cand.filter(c=>c.ok),3).concat(sample(cand.filter(c=>!c.ok),2)));
return {type:'multi',q:'Какие из этих тестов — <b>крайние случаи</b> из чек-листа? Выбери все.',opts:opts.map(o=>o.t),ans:opts.map((o,i)=>o.ok?i:-1).filter(i=>i>=0),
short:'Крайние: одно число, подходящих нет, граница условия, нужное число первое/последнее.',
explain:`Чек-лист: одно число; все одинаковые; подходящих нет; все подходят; нужное число первое или последнее; граница условия; самые большие числа.<br>${opts.map(o=>`• ${o.t} — ${o.ok?'<b>крайний</b>':'обычный'}`).join('<br>')}`,
explain2:'Крайний тест «давит» на слабое место программы: стартовое значение (одно число, нет подходящих), сравнение (граница), начало и конец цикла (первое и последнее число). «Удобные» тесты ни на что не давят.'};},{rule:true});
G(6,()=>{const k=pick([4,6,8]),d=pick([2,6]);let y=d+10;while(y%k===0)y+=10;
const code=`n = int(input())\nc = 0\nfor i in range(n):\n    x = int(input())\n    if x % ${k} == 0 or x % 10 == ${d}:\n        c += 1\nprint(c)`;
const ok=`в условии нужно and вместо or`;
const opts=shuffle([ok,'range(n) надо заменить на range(1, n)','c надо начинать с 1','print(c) надо сдвинуть внутрь цикла']);
return {type:'choice',q:`Программа должна считать числа, кратные ${k} <b>и</b> оканчивающиеся на ${d}. На вводе 2, числа ${k*10}, ${y} она печатает неверный ответ. В чём ошибка?${C(code)}`,opts,ans:opts.indexOf(ok),
short:'«И» — это and. С or посчитаются числа, у которых выполнено только одно условие.',
explain:`Условие «кратно ${k} <b>и</b> оканчивается на ${d}» — нужны оба, значит <code>and</code>.<br>С <code>or</code>: ${k*10} кратно ${k}, но оканчивается на 0 — всё равно посчитано. Число ${y} оканчивается на ${d}, но не кратно ${k} — тоже посчитано. Программа выдаст 2 вместо 0.<br>Остальные «исправления» сломают правильные части: range(1, n) потеряет число, c = 1 даст лишнюю единицу, print внутри цикла напечатает много строк.`,
explain2:'Переведи условие задачи на Python дословно: «кратно … И оканчивается …» → <code>x % k == 0 and x % 10 == d</code>. Слово «и» в условии почти всегда означает and, «или» / «хотя бы одно» — or.'};});
G(6,()=>{const code=`s = 0\nx = int(input())\nwhile x != 0:\n    s = s + x\nprint(s)`;
const ok='внутри цикла не читается новое число — цикл бесконечный';
const opts=shuffle([ok,'s нужно начинать с 1','условие должно быть x == 0','первую строку input() нужно убрать']);
return {type:'choice',q:`Программа должна сложить числа до нуля. Что с ней не так?${C(code)}`,opts,ans:opts.indexOf(ok),
short:'Без x = int(input()) в теле цикла x не меняется — while крутится вечно.',
explain:`Если первое число 5, то условие 5 != 0 верно, s = 5, потом снова 5 != 0, s = 10, … x <b>никогда не меняется</b>, поэтому цикл бесконечный.<br>Исправление — последней строкой тела цикла: <code>x = int(input())</code>.`,
explain2:'В цикле while что-то обязательно должно меняться так, чтобы условие когда-нибудь стало ложным. Тут условие зависит от x — значит, x должен меняться внутри цикла. Спроси себя у каждого while: «Что здесь меняется и когда это закончится?»'};});
G(6,()=>{
const mk=n=>rl(n,1,30000).map(x=>x-x%3);
const ins=[mk(5).map(x=>x||3),[3],[30000,29997],[9,10,11,6],mk(7).map(x=>x||3),[1,2,4,27]];
const f=a=>Math.min(...a.filter(x=>x%3===0));
const tests=ins.map(a=>({in:J([a.length].concat(a)),out:String(f(a))}));
return {type:'code',q:`<b>Найди и исправь ошибку.</b> Программа должна находить минимальное число, кратное 3, из n натуральных чисел (числа ≤ 30 000, хотя бы одно кратно 3). Запусти заготовку на тестах — она ошибается. Исправь.`,
starter:`n = int(input())\nm = 0\nfor i in range(n):\n    x = int(input())\n    if x % 3 == 0 and x < m:\n        m = x\nprint(m)`,
solution:`n = int(input())\nm = 30001\nfor i in range(n):\n    x = int(input())\n    if x % 3 == 0 and x < m:\n        m = x\nprint(m)`,tests,
hint:'Посмотри на результаты тестов: программа всё время печатает одно и то же число. Откуда оно берётся?',
explain:`Заготовка всегда печатает 0: условие <code>x &lt; m</code> при m = 0 не выполняется ни для одного натурального x.<br>Исправление: <code>m = 30001</code> — больше любого числа из ограничения. Тест «30000, 29997» — крайний: числа близки к границе, проверяет, что старт действительно больше всех.`,
explain2:'Подход «отладчика»: запусти на самом простом тесте (одно число 3). Ожидается 3, печатается 0. Трассируй: m = 0, x = 3, 3 &lt; 0? Нет. Значит, проблема в стартовом значении.'};});

/* ---------- L7: ★ формулы ---------- */
G(7,()=>{const a=R(10,60),b=pick([3,4,6,7,8]);const ans=Math.floor((a+b-1)/b);const ok='(a + b - 1) // b';
const opts=shuffle([ok,'a // b','a // b + 1','(a - 1) // b']);
return {type:'choice',q:`Сколько коробок по b штук нужно для a предметов (лишние места можно оставить пустыми)? Какая формула всегда верна?`,opts:opts.map(ic),ans:opts.indexOf(ok),
short:`(a + b − 1) // b — деление с округлением вверх. Например, a = ${a}, b = ${b}: ${ans}.`,
explain:`Нужно деление <b>с округлением вверх</b>: <code>(a + b - 1) // b</code>.<br>Пример: a = ${a}, b = ${b} → (${a} + ${b-1}) // ${b} = ${ans}.<br>• <code>a // b</code> = ${Math.floor(a/b)} — округляет вниз, остатку предметов не хватит коробки${a%b===0?' (здесь случайно верно, потому что делится нацело)':''}.<br>• <code>a // b + 1</code> — неверно, когда делится нацело: 8 предметов по 4 → 3 коробки вместо 2.<br>• <code>(a - 1) // b</code> — ещё меньше, чем a // b.`,
explain2:'Почему работает: прибавив b − 1, мы «докладываем» почти полную коробку. Если был хоть один лишний предмет, он вместе с добавкой заполнит новую коробку целиком, и // её посчитает. Если остатка не было, добавки b − 1 не хватит на новую коробку — лишней не будет.'};},{star:true,rule:true});
G(7,()=>{const tests=[['6 6 4','4'],['1 1 1','1'],['2 1 1','2'],['1000000000 1000000000 1','1000000000000000000'],['12 13 4','12'],['3 3 5','1'],['7 1 3','3']].map(t=>({in:t[0],out:t[1]}));
return {type:'code',q:`<b>★ Театральная площадь</b> (по мотивам Codeforces 1A). Площадь — прямоугольник n × m метров. Её мостят квадратными плитками a × a. Плитки нельзя резать, но можно выходить за края площади. Какое наименьшее число плиток нужно? Ввод: n, m, a в одной строке через пробел (1 ≤ n, m, a ≤ 10⁹).<br>Пример: «6 6 4» → 4.`,
starter:`n, m, a = map(int, input().split())\n`,
solution:`n, m, a = map(int, input().split())\nprint(((n + a - 1) // a) * ((m + a - 1) // a))`,tests,
hint:'По каждой стороне отдельно: сколько плиток нужно на сторону n? Это деление с округлением вверх. Потом перемножь.',
explain:`На сторону n нужно ⌈n / a⌉ плиток (округление вверх), на сторону m — ⌈m / a⌉. Всего — произведение.<br>В Python: <code>((n + a - 1) // a) * ((m + a - 1) // a)</code>.<br>Крайние тесты: плитка больше площади (3 3 5 → 1); огромная площадь 10⁹ × 10⁹ при a = 1 → 10¹⁸ (цикл тут бы не успел, а формула мгновенна).`,
explain2:`Не используй <code>/</code> и round: <code>/</code> даёт дробь, а для огромных чисел дробь хранится неточно. Целочисленная формула с <code>//</code> всегда точна. Пример 12 × 13, a = 4: по 12 → 3 плитки, по 13 → (13 + 3) // 4 = 4 плитки, итого 12.`};},{star:true});
G(7,()=>{const tests=[['3 17 4','13'],['2 100 3','0'],['1 0 1','1'],['1000 0 1000','500500000'],['5 15 2','0'],['10 1 3','59']].map(t=>({in:t[0],out:t[1]}));
return {type:'code',q:`<b>★ Солдат и бананы</b> (по мотивам Codeforces 546A). Солдат хочет купить w бананов. Первый стоит k рублей, второй — 2k, третий — 3k, и так далее (i-й банан стоит i·k). У него n рублей. Сколько рублей ему нужно занять у друга? Если денег хватает — выведи 0. Ввод: k, n, w в одной строке.<br>Пример: «3 17 4» → цена 3 + 6 + 9 + 12 = 30, занять 30 − 17 = 13.`,
starter:`k, n, w = map(int, input().split())\n`,
solution:`k, n, w = map(int, input().split())\ncost = k * w * (w + 1) // 2\nprint(max(0, cost - n))`,tests,
hint:'Цена всех бананов: k·(1 + 2 + … + w). Сумма 1 + … + w = w·(w + 1) / 2 — или посчитай циклом. Не забудь случай, когда денег хватает.',
explain:`1) Цена: k + 2k + … + wk = k·(1 + 2 + … + w) = k·w·(w + 1) / 2. В Python: <code>k * w * (w + 1) // 2</code> (произведение w·(w + 1) всегда чётное, деление точное).<br>2) Занять: цена − n, но не меньше нуля: <code>max(0, cost - n)</code>.<br>Крайний тест «2 100 3»: цена 12, денег 100 → 0, а не −88!`,
explain2:'Можно и циклом: <code>for i in range(1, w + 1): cost += i * k</code> — при w ≤ 1000 это быстро. Главная ловушка задачи не в формуле, а в отрицательном ответе: если денег больше, чем нужно, занимать надо 0.'};},{star:true});
G(7,()=>{const tests=[['8','YES'],['2','NO'],['1','NO'],['3','NO'],['100','YES'],['4','YES'],['7','NO']].map(t=>({in:t[0],out:t[1]}));
return {type:'code',q:`<b>★ Арбуз</b> (по мотивам Codeforces 4A). Петя и Вася купили арбуз весом w килограммов (w — целое, 1 ≤ w ≤ 100). Они хотят разрезать его на две части так, чтобы <b>каждая</b> часть весила чётное число килограммов (больше нуля). Можно ли это сделать? Выведи YES или NO.<br>Пример: 8 → YES (2 + 6 или 4 + 4).`,
starter:`w = int(input())\nif w % 2 == 0:\n    print("YES")\nelse:\n    print("NO")`,
solution:`w = int(input())\nif w % 2 == 0 and w > 2:\n    print("YES")\nelse:\n    print("NO")`,tests,
hint:'Заготовка почти верная, но падает на одном крайнем тесте. Подумай про самый маленький чётный вес.',
explain:`Если w нечётное — две чётные части в сумме дадут чётное число, значит, нельзя. Если w чётное — можно 2 + (w − 2), но только если w − 2 &gt; 0, то есть <b>w &gt; 2</b>.<br>w = 2: 2 = 1 + 1 (нечётные) или 2 + 0 (ноль не годится) → NO.<br>Условие: <code>w % 2 == 0 and w &gt; 2</code>.`,
explain2:'Это тот самый «тест-убийца» из стратегии: самое маленькое значение, которое подходит под общее правило «чётное → YES», но на самом деле — исключение. Проверяй всегда самые маленькие входы: 1, 2, 3.'};},{star:true});

/* ---------- L8: ★ строки и серии ---------- */
G(8,()=>{const pr=pick([[2,3],[3,5],[2,5],[3,7],[4,6]]);const a=pr[0],b=pr[1];const N=R(100,999);let c=0;for(let i=1;i<=N;i++)if(i%a===0||i%b===0)c++;const l=a*b/H.gcd(a,b);
return {type:'num',q:`<b>★</b> Сколько натуральных чисел от 1 до ${N} делятся на ${a} <b>или</b> на ${b} (хотя бы на одно)? Реши формулой, без цикла.`,ans:c,
hint:`Посчитай кратные ${a}, кратные ${b} и вычти тех, кого посчитал дважды — кратных ${l}.`,
short:`${N} // ${a} + ${N} // ${b} − ${N} // ${l} = ${Math.floor(N/a)} + ${Math.floor(N/b)} − ${Math.floor(N/l)} = ${c}.`,
explain:`Кратных ${a} от 1 до ${N}: ${N} // ${a} = ${Math.floor(N/a)}.<br>Кратных ${b}: ${N} // ${b} = ${Math.floor(N/b)}.<br>Числа, кратные обоим (то есть кратные НОК(${a}, ${b}) = ${l}), попали в оба списка: ${N} // ${l} = ${Math.floor(N/l)}. Вычитаем их один раз.<br>Ответ: ${Math.floor(N/a)} + ${Math.floor(N/b)} − ${Math.floor(N/l)} = <b>${c}</b>.`,
explain2:`Проверка на маленьком примере: от 1 до ${l}: кратные ${a} — ${range(a,l,a).join(', ')}; кратные ${b} — ${range(b,l,b).join(', ')}. Число ${l} есть в обоих списках — без вычитания его посчитали бы дважды. Это формула включений-исключений, как в задачах про кружки и секции.`};},{star:true});
G(8,()=>{const tests=[['4\nword\nlocalization\ninternationalization\npneumonoultramicroscopicsilicovolcanoconiosis','word\nl10n\ni18n\np43s'],['1\nabcdefghij','abcdefghij'],['1\nabcdefghijk','a9k'],['2\nпрограммирование\nкот','п14е\nкот'],['3\na\nкомпьютерный\nxx','a\nк10й\nxx']].map(t=>({in:t[0],out:t[1]}));
return {type:'code',q:`<b>★ Слишком длинные слова</b> (по мотивам Codeforces 71A). Слово считается слишком длинным, если в нём <b>строго больше 10</b> букв. Такое слово заменяют сокращением: первая буква + количество букв между первой и последней + последняя буква. Например, «localization» → «l10n». Короткие слова выводят без изменений. Ввод: n, затем n слов (каждое в своей строке).`,
starter:`n = int(input())\nfor i in range(n):\n    w = input()\n    print(w)`,
solution:`n = int(input())\nfor i in range(n):\n    w = input()\n    if len(w) > 10:\n        print(w[0] + str(len(w) - 2) + w[-1])\n    else:\n        print(w)`,tests,
hint:'Первая буква — w[0], последняя — w[-1], букв между ними — len(w) − 2. Число превращаем в текст через str().',
explain:`Для каждого слова: если <code>len(w) &gt; 10</code> → печатаем <code>w[0] + str(len(w) - 2) + w[-1]</code>, иначе — само слово.<br>На примере: «localization» — 12 букв, между первой и последней 12 − 2 = 10 → «l10n».<br>Крайние тесты: ровно 10 букв (не сокращаем!) и 11 букв (сокращаем: «a9k»).`,
explain2:'Частые ошибки: <code>len(w) &gt;= 10</code> (слово из 10 букв сократится, а не должно), <code>len(w) - 1</code> вместо − 2 (между первой и последней на две буквы меньше, чем всего), склеивание числа с текстом без str() — TypeError.'};},{star:true});
G(8,()=>{const cols='RGB';const mk=n=>Array.from({length:n},()=>pick([...cols])).join('');
const f=s=>{let k=0;for(let i=1;i<s.length;i++)if(s[i]===s[i-1])k++;return k;};
const ins=[mk(8),'R','RRRRR','RGBRGB',mk(12),'RRGBBB'];
const tests=ins.map(s=>({in:s.length+'\n'+s,out:String(f(s))}));
return {type:'code',q:`<b>★ Камни на столе</b> (по мотивам Codeforces 266A). В ряд лежат n камней, цвет каждого — R, G или B. Какое наименьшее число камней надо убрать, чтобы любые два соседних камня были разного цвета? Ввод: n, затем строка из n букв.<br>Пример: 6 и RRGBBB → 3.`,
starter:`n = int(input())\ns = input()\nk = 0\n`,
solution:`n = int(input())\ns = input()\nk = 0\nfor i in range(1, n):\n    if s[i] == s[i - 1]:\n        k += 1\nprint(k)`,tests,
hint:'Каждая пара одинаковых соседей требует убрать один камень. Сравни s[i] и s[i − 1] для i от 1.',
explain:`Если два соседа одного цвета, один из них лишний. Значит, ответ — <b>количество пар соседей одного цвета</b>.<br>Цикл <code>for i in range(1, n)</code> (с 1, чтобы у s[i] был сосед слева) и <code>if s[i] == s[i - 1]: k += 1</code>.<br>Крайние: один камень → 0; RRRRR → 4 (оставить один); RGBRGB → 0.`,
explain2:'Почему не нужно «по-настоящему» удалять камни: в серии из одинаковых камней длины L убрать надо L − 1, а одинаковых соседних пар в ней как раз L − 1. Задача сводится к простому счётчику — так часто бывает на олимпиадах: подумай, прежде чем моделировать.'};},{star:true});
G(8,()=>{
const mk=n=>{const a=[];while(a.length<n){const v=R(1,5);const L=R(1,4);for(let j=0;j<L&&a.length<n;j++)a.push(v);}return a;};
const f=a=>{let best=0,cur=0,prev=0;for(const x of a){cur=x===prev?cur+1:1;if(cur>best)best=cur;prev=x;}return best;};
const ins=[mk(10),[7],[3,3,3,3],[1,2,3,4],[5,5,2,2,2,7,7,7,7],mk(15)];
const tests=ins.map(a=>({in:J(a.concat([0])),out:String(f(a))}));
return {type:'code',q:`<b>★ Самая длинная серия</b> (школьный этап ВсОШ, адаптировано). Вводятся натуральные числа, каждое в своей строке, конец — 0. Найди длину самой длинной серии <b>одинаковых чисел, идущих подряд</b>.<br>Пример: 5, 5, 2, 2, 2, 7, 0 → 3.`,
starter:`best = 0\ncur = 0\nprev = 0\nx = int(input())\nwhile x != 0:\n    # сравни x с prev\n\n    x = int(input())\nprint(best)`,
solution:`best = 0\ncur = 0\nprev = 0\nx = int(input())\nwhile x != 0:\n    if x == prev:\n        cur += 1\n    else:\n        cur = 1\n    if cur > best:\n        best = cur\n    prev = x\n    x = int(input())\nprint(best)`,tests,
hint:'Если x равно предыдущему — серия продолжается (cur += 1), иначе начинается новая (cur = 1). После этого обнови best и запомни prev = x.',
explain:`Храним три вещи: prev — предыдущее число, cur — длина текущей серии, best — рекорд.<br>Для каждого x: если <code>x == prev</code> → <code>cur += 1</code>, иначе <code>cur = 1</code>. Затем <code>if cur &gt; best: best = cur</code>, и <code>prev = x</code>.<br>prev = 0 в начале работает, потому что 0 не бывает среди чисел.<br>Крайние: одно число → 1; все одинаковые; самая длинная серия в самом конце (поэтому best обновляем на каждом шаге, а не только при смене числа).`,
explain2:`Трассировка 5, 5, 2, 2, 2, 7: x=5 (≠0) cur=1 best=1; x=5 cur=2 best=2; x=2 cur=1; x=2 cur=2; x=2 cur=3 best=3; x=7 cur=1. Ответ 3. Типичная ошибка — обновлять best только когда серия «оборвалась»: тогда последняя серия не учтётся.`};},{star:true});

